def transform(grid):
    row_starts = (1, 6, 11)
    col_starts = (1, 6)

    tiles = []
    for r in row_starts:
        for c in col_starts:
            pattern = tuple(
                tuple(grid[r + i][c + j] == 2 for j in range(4))
                for i in range(4)
            )
            count = sum(sum(row) for row in pattern)
            tiles.append((pattern, count))

    # The fullest tile is the reference pattern.
    reference_index = max(range(len(tiles)), key=lambda k: tiles[k][1])
    reference = tiles[reference_index][0]

    out = [row[:] for row in grid]
    seen_patterns = set()

    for k, (pattern, _) in enumerate(tiles):
        r = row_starts[k // 2]
        c = col_starts[k % 2]

        if k == reference_index:
            color = 3
        elif (pattern not in seen_patterns and
              all(not pattern[i][j] or reference[i][j]
                  for i in range(4) for j in range(4))):
            color = 8
            seen_patterns.add(pattern)
        else:
            color = 2

        if color != 2:
            for i in range(4):
                for j in range(4):
                    if out[r + i][c + j] == 2:
                        out[r + i][c + j] = color

    return out
